arguments.command:
cd /app/submission && grep -n "print(\|DBG\|TODO\|FIXME\|XXX" main.py; echo "--- unused check ---"; python3 - << 'EOF'
import ast, sys
src = open('/app/submission/main.py').read()
tree = ast.parse(src)
assigned = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
        assigned.add(node.id)
used = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
        used.add(node.id)
top_funcs = {n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef))}
imports = {a.asname or a.name.split('.')[0] for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom)) for a in n.names}
print("unused module-level imports:", sorted(i for i in imports if i not in used))
print("module-level defs never referenced:", sorted(f for f in top_funcs if f not in used and f != 'main'))
EOF
chmod +x main.py run.sh; ls -la /app/submission
